SELECT hostName() AS hostname,version() AS version,uptime() AS uptime_s,(SELECT value FROM system.asynchronous_metrics WHERE metric='CGroupMaxCPU') AS vCPUs,(SELECT value FROM system.asynchronous_metrics WHERE metric='CGroupMemoryTotal') AS memory_bytes LIMIT 1 SETTINGS max_threads=2,max_execution_time=30,timeout_before_checking_execution_speed=0,max_rows_to_read=1000000000,max_bytes_to_read=100000000000,skip_unavailable_shards=0 FORMAT CSVWithNames
